  void sse_encode_wire_upbit_smp_type(
    WireUpbitSmpType self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.index, serializer);
  }

  @protected
  void sse_encode_wire_upbit_subscription_list(
    WireUpbitSubscriptionList self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.ticket, serializer);
    sse_encode_list_wire_upbit_listed_subscription(
      self.subscriptions,
      serializer,
    );
  }

  @protected
  void sse_encode_wire_upbit_travel_rule_vasp(
    WireUpbitTravelRuleVasp self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.vaspName, serializer);
    sse_encode_String(self.vaspUuid, serializer);
    sse_encode_bool(self.depositable, serializer);
    sse_encode_bool(self.withdrawable, serializer);
  }

  @protected
  void sse_encode_wire_upbit_travel_rule_verification(
    WireUpbitTravelRuleVerification self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.depositUuid, serializer);
    sse_encode_String(self.depositState, serializer);
    sse_encode_String(self.verificationResult, serializer);
  }

  @protected
  void sse_encode_wire_upbit_withdrawal_address(
    WireUpbitWithdrawalAddress self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.currency, serializer);
    sse_encode_String(self.netType, serializer);
    sse_encode_String(self.networkName, serializer);
    sse_encode_String(self.withdrawAddress, serializer);
    sse_encode_opt_String(self.secondaryAddress, serializer);
    sse_encode_opt_String(self.beneficiaryName, serializer);
    sse_encode_opt_String(self.beneficiaryCompanyName, serializer);
    sse_encode_opt_String(self.beneficiaryType, serializer);
    sse_encode_opt_String(self.exchangeName, serializer);
    sse_encode_opt_String(self.walletType, serializer);
    sse_encode_String(self.rawJson, serializer);
  }

  @protected
  void sse_encode_wire_upbit_year_candle(
    WireUpbitYearCandle self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_wire_market(self.market, serializer);
    sse_encode_i_64(self.openTimeNs, serializer);
    sse_encode_opt_box_autoadd_i_64(self.koreaOpenTimeNs, serializer);
    sse_encode_i_64(self.timestampNs, serializer);
    sse_encode_String(self.open, serializer);
    sse_encode_String(self.high, serializer);
    sse_encode_String(self.low, serializer);
    sse_encode_String(self.close, serializer);
    sse_encode_String(self.volume, serializer);
    sse_encode_String(self.quoteVolume, serializer);
    sse_encode_String(self.firstDayOfPeriod, serializer);
  }

  @protected
  void sse_encode_wire_withdraw_request(
    WireWithdrawRequest self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.asset, serializer);
    sse_encode_String(self.network, serializer);
    sse_encode_String(self.amount, serializer);
    sse_encode_wire_transfer_destination(self.destination, serializer);
    sse_encode_opt_String(self.clientId, serializer);
  }

  @protected
  void sse_encode_wire_withdrawal(
    WireWithdrawal self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.id, serializer);
    sse_encode_String(self.asset, serializer);
    sse_encode_opt_String(self.network, serializer);
    sse_encode_opt_String(self.providerNetwork, serializer);
    sse_encode_String(self.amount, serializer);
    sse_encode_opt_String(self.fee, serializer);
    sse_encode_opt_box_autoadd_wire_transfer_destination(
      self.destination,
      serializer,
    );
    sse_encode_wire_withdrawal_status(self.status, serializer);
    sse_encode_String(self.providerStatus, serializer);
    sse_encode_opt_String(self.txId, serializer);
    sse_encode_opt_box_autoadd_i_64(self.createdAtNs, serializer);
  }

  @protected
  void sse_encode_wire_withdrawal_fee(
    WireWithdrawalFee self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case WireWithdrawalFee_Fixed(field0: final field0):
        sse_encode_i_32(0, serializer);
        sse_encode_String(field0, serializer);
      case WireWithdrawalFee_Rate(
        rate: final rate,
        minimum: final minimum,
        maximum: final maximum,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_String(rate, serializer);
        sse_encode_opt_String(minimum, serializer);
        sse_encode_opt_String(maximum, serializer);
    }
  }

  @protected
  void sse_encode_wire_withdrawal_page(
    WireWithdrawalPage self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_list_wire_withdrawal(self.items, serializer);
    sse_encode_opt_String(self.next, serializer);
  }

  @protected
  void sse_encode_wire_withdrawal_quote(
    WireWithdrawalQuote self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_opt_String(self.fee, serializer);
    sse_encode_opt_String(self.expectedReceive, serializer);
    sse_encode_opt_String(self.minimumAmount, serializer);
    sse_encode_opt_String(self.maximumAmount, serializer);
    sse_encode_opt_box_autoadd_bool(self.addressAllowed, serializer);
    sse_encode_wire_travel_rule_requirement(self.travelRule, serializer);
    sse_encode_opt_box_autoadd_i_64(self.expiresAtNs, serializer);
  }

  @protected
  void sse_encode_wire_withdrawal_status(
    WireWithdrawalStatus self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.index, serializer);
  }
}

